{
  "findings": [
    {
      "check_id": "CKV_AZURE_1",
      "title": "Hardcoded sensitive value in Key Vault secret",
      "resource": "azurerm_key_vault_secret.database_connection_string",
      "severity": "CRITICAL",
      "explanation": "The 'value' field contains a hardcoded sensitive value (database connection string). Hardcoding sensitive information in Terraform files poses a significant security risk as it can be exposed in version control systems or logs."
    }
  ],
  "patched_code": "resource \"azurerm_key_vault_secret\" \"database_connection_string\" {\n  name         = \"database-connection-string\"\n  value        = var.database_connection_string\n  key_vault_id = azurerm_key_vault.legal_keyvault.id\n  depends_on   = [azurerm_mssql_database.legal_metadata_db]\n}\n\nvariable \"database_connection_string\" {\n  description = \"The database connection string.\"\n  type        = string\n  sensitive   = true\n}",
  "fix_summary": "Replaced the hardcoded sensitive value in the 'value' field with a reference to a sensitive input variable 'database_connection_string'. Added a new sensitive variable definition for 'database_connection_string'."
}
